def main():
    """Main function"""

    module = gcp_v2.Module(
        argument_spec=dict(
            filters=dict(
                type="list",
                elements="str",
            ),
            region=dict(
                type="str",
            ),
        ),
        supports_check_mode=True,
    )

    if not module.params["scopes"]:
        module.params["scopes"] = ["https://www.googleapis.com/auth/cloud-platform"]

    # info modules only require the "collection" url
    op_configs = gcp_v2.ResourceOpConfigs(
        base_url="https://{region}-aiplatform.googleapis.com/v1/",
        base_uri="projects/{project}/locations/{region}/reasoningEngines",
        configs={},
    )

    info = gcp_v2.Resource(
        module.params,  # only need it to build the link
        module=module,
        product="VertexAI",
        kind="vertexai#reasoningEngine",
        op_configs=op_configs,
    )

    filter_exprs = module.params.get("filters") or []

    link = info.build_link("list")
    resources = info.list(link, key="reasoningEngines", filters=filter_exprs)

    module.exit_json(changed=False, resources=resources)


if __name__ == "__main__":
    main()
